import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;
import org.json.JSONObject;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        response.setContentType("application/json");
        PrintWriter out = response.getWriter();

        String sessionToken = request.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            response.setStatus(401);
            out.print("{\"error\": \"unauthorized\"}");
            return;
        }

        String reportType = request.getParameter("report_type");
        String dateFrom = request.getParameter("date_from");
        String dateTo = request.getParameter("date_to");
        String sortColumn = request.getParameter("sort_by");
        String filterExpr = request.getParameter("filter");

        if (reportType == null || dateFrom == null || dateTo == null) {
            response.setStatus(400);
            out.print("{\"error\": \"missing required parameters\"}");
            return;
        }

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            response.setStatus(400);
            out.print("{\"error\": \"invalid report type\"}");
            return;
        }

        // Validate sort column uses safe identifier pattern
        if (sortColumn != null && !SAFE_IDENTIFIER.matcher(sortColumn).matches()) {
            response.setStatus(400);
            out.print("{\"error\": \"invalid sort column\"}");
            return;
        }

        try {
            Connection conn = getConnection();
            String query = buildReportQuery(reportType, dateFrom, dateTo, sortColumn, filterExpr);
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnName(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");

            out.print(json.toString());
            rs.close();
            stmt.close();
            conn.close();

        } catch (SQLException e) {
            response.setStatus(500);
            out.print("{\"error\": \"query execution failed\"}");
        }
    }

    private String buildReportQuery(String reportType, String dateFrom, String dateTo,
                                     String sortColumn, String filterExpr) {
        String baseTable = getTableForReport(reportType);
        StringBuilder query = new StringBuilder();
        query.append("SELECT * FROM ").append(baseTable);
        query.append(" WHERE created_at >= '").append(dateFrom).append("'");
        query.append(" AND created_at <= '").append(dateTo).append("'");

        // Apply custom filter expression if provided
        if (filterExpr != null && !filterExpr.isEmpty()) {
            query.append(" AND (").append(filterExpr).append(")");
        }

        if (sortColumn != null) {
            query.append(" ORDER BY ").append(sortColumn);
        }

        return query.toString();
    }

    private boolean isValidReportType(String type) {
        return type.equals("sales") || type.equals("inventory") || 
               type.equals("customers") || type.equals("orders");
    }

    private String getTableForReport(String type) {
        switch(type) {
            case "sales": return "report_sales";
            case "inventory": return "report_inventory";
            case "customers": return "report_customers";
            case "orders": return "report_orders";
            default: return "report_sales";
        }
    }

    private boolean validateSession(String token) {
        // Validates against session store
        return token != null && token.length() == 64;
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
